import json,os
def find_cups(g):
    seen=set(); cups=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]==5 and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen or not(0<=y<H and 0<=x<W) or g[y][x]!=5: continue
                    seen.add((y,x)); comp.append((y,x))
                    st+=[(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                if len(comp)>4: cups.append(comp)
    return cups

def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    for comp in find_cups(g):
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        top,bot,l,r=min(ys),max(ys),min(xs),max(xs)
        # cavity: zeros inside bbox not reachable from outside through zeros
        from collections import deque
        out=set(); dq=deque()
        for i in range(H):
            for j in range(W):
                if (i in (0,H-1) or j in (0,W-1)) and g[i][j]==0: dq.append((i,j)); out.add((i,j))
        while dq:
            y,x=dq.popleft()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]==0 and (ny,nx) not in out:
                    out.add((ny,nx)); dq.append((ny,nx))
        for i in range(top,bot+1):
            for j in range(l,r+1):
                if g[i][j]==0 and (i,j) not in out: g[i][j]=2
        # gap in top row
        gap=[j for j in range(l,r+1) if g[top][j]==0][0]
        g[top][gap]=2
        nleft=sum(1 for j in range(l,gap) if g[top][j]==5)
        nright=sum(1 for j in range(gap+1,r+1) if g[top][j]==5)
        if nleft>=nright: rng=range(0,gap+1)
        else: rng=range(gap,W)
        for j in rng: g[top-1][j]=2
    return g

